package dev.pocketengine.runtime.routes;

import dev.pocketengine.core.NativeToolPlan;
import dev.pocketengine.core.PhonePort;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.runtime.policy.PhoneActionPolicy;
import java.util.Set;
import org.json.JSONArray;
import org.json.JSONObject;

/** Bounded suggestions from owner-confirmed runs. The original Runner alone dispatches every step. */
public final class PhoneRouteSession {
    public static final String LIST="phone_routes",REPLAY="phone_replay_route",FORGET="phone_forget_route";
    public interface Repository {
        JSONArray routes(String exactGoal,RunControl original)throws Exception;
        JSONObject route(String routeId,String digest,String exactGoal,RunControl original)throws Exception;
        void withdraw(String routeId,String digest,RunControl original)throws Exception;
        long packageVersion(String packageName)throws Exception;
        String hostUserIdentity()throws Exception;
    }
    public interface Factory {Repository forRun(String taskId,RunControl original)throws Exception;}
    private static volatile Factory factory;
    public static void installFactory(Factory host){factory=java.util.Objects.requireNonNull(host);}
    public static PhoneRouteSession open(String task,String goal,PhonePort phone,RunControl original,boolean restored)throws Exception {Factory host=factory;if(host==null||phone==null)return null;try{Repository repository=host.forRun(task,original);return repository==null?null:new PhoneRouteSession(task,goal,phone,original,repository,restored);}catch(InterruptedException stopped){throw stopped;}catch(Exception unavailable){original.check();return null;}}
    private final String task,goal;private final PhonePort phone;private final RunControl original;private final Repository repository;private final boolean restored;
    private final JSONArray learned=new JSONArray(),operations=new JSONArray();private String packageName="";private long version;private boolean invalid,replaying;private NativeToolPlan prepared;private String preparedCall;private JSONObject replayRoute;private int resolvedStep=-1;
    public PhoneRouteSession(String task,String goal,PhonePort phone,RunControl original,Repository repository,boolean restored){this.task=task;this.goal=goal;this.phone=phone;this.original=original;this.repository=java.util.Objects.requireNonNull(repository);this.restored=restored;}
    public static boolean supports(String tool){return Set.of(LIST,REPLAY,FORGET).contains(tool);}
    public boolean replayAllowed(){return !restored;}
    public static void validate(String name,JSONObject args)throws Exception {if(!supports(name)||LIST.equals(name)&&args.length()!=0||!LIST.equals(name)&&(args.length()!=2||!args.optString("routeId").matches("[a-f0-9-]{36}")||!args.optString("digest").matches("[a-f0-9]{64}")))throw new IllegalArgumentException("路线仅接受当前目录的准确routeId/digest，不接受动作、坐标、槽或新权限");}
    public JSONArray tools()throws Exception {JSONArray out=new JSONArray();for(String name:restored?new String[]{LIST,FORGET}:new String[]{LIST,REPLAY,FORGET}){JSONObject properties=LIST.equals(name)?new JSONObject():new JSONObject().put("routeId",new JSONObject().put("type","string").put("maxLength",36)).put("digest",new JSONObject().put("type","string").put("maxLength",64));out.put(new JSONObject().put("type","function").put("function",new JSONObject().put("name",name).put("description",LIST.equals(name)?"列同一精确目标中主人已确认成功的低风险导航路线；只作建议，不恢复旧动作权限。":REPLAY.equals(name)?"尝试准确成功路线的最多4个低风险树动作。每步重新观察、核app版本和唯一语义目标，偏离立即回原模型，已做步骤不重跑。":"撤回一条准确路线，后续任务和当前未派发步骤都不可继续调用。").put("parameters",new JSONObject().put("type","object").put("properties",properties).put("required",LIST.equals(name)?new JSONArray():new JSONArray().put("routeId").put("digest")).put("additionalProperties",false))));}return out;}
    public JSONObject execute(String name,JSONObject args,JSONObject latest,String call,RunControl live)throws Exception {
        require(live);validate(name,args);if(LIST.equals(name))return new JSONObject().put("ok",true).put("routes",repository.routes(goal,live)).put("automaticReplay",false);
        String id=args.getString("routeId"),digest=args.getString("digest");if(FORGET.equals(name)){repository.withdraw(id,digest,live);return new JSONObject().put("ok",true).put("withdrawn",true).put("routeId",id);}
        if(restored)throw new SecurityException("恢复中的原任务不从头回放路线");if(replaying)return new JSONObject().put("ok",false).put("accepted",false).put("code","route_already_attempted").put("message","此原运行已尝试一次路线；已做步骤保留，不能从头回放，请按当前现场规划。");JSONObject route=repository.route(id,digest,goal,live);JSONArray steps=route.getJSONArray("steps");checkRoute(route,latest);
        JSONObject binding=new JSONObject(latest.getJSONObject("observationBinding").toString());String hostUser=repository.hostUserIdentity();NativeToolPlan.Identity identity=new NativeToolPlan.Identity(task,binding.getString("runId"),binding.getInt("epoch"),binding.getInt("displayId"),binding.getString("sessionId"),hostUser,latest.getString("observationId"));
        RunControl.AuthorityCheck current=()->{require(original);repository.route(id,digest,goal,original);if(!hostUser.equals(repository.hostUserIdentity())||repository.packageVersion(route.getString("packageName"))!=route.getLong("packageVersion"))throw new SecurityException("路线app版本或原进程用户身份已改变");};
        if(prepared!=null)prepared.close();prepared=NativeToolPlan.capture(REPLAY,call,original,identity,steps.length(),(index,control)->{
            current.check();JSONObject fresh=phone.observe(false,control);checkRoute(route,fresh);JSONObject currentBinding=fresh.getJSONObject("observationBinding");if(!task.equals(currentBinding.optString("taskId"))||!binding.getString("runId").equals(currentBinding.optString("runId"))||binding.getInt("epoch")!=currentBinding.optInt("epoch")||!binding.get("displayId").equals(currentBinding.get("displayId"))||!binding.getString("sessionId").equals(currentBinding.getString("sessionId")))throw new SecurityException("路线原任务、显示或会话改变");JSONObject step=steps.getJSONObject(index);if(!anchorsMatch(fresh,step.optJSONArray("beforeAnchors")))throw new SecurityException("路线当前页面锚点偏离");JSONObject target=unique(fresh,step.getJSONObject("selector"));String tool=step.getString("tool");JSONObject actual=new JSONObject().put("observationId",fresh.getString("observationId")).put("nodeId",target.getString("id"));if(tool.equals("phone_scroll_node"))actual.put("direction",step.getString("direction"));if(PhoneActionPolicy.before(tool,actual,fresh)!=null)throw new SecurityException("路线遇到财务承诺，未派发");resolvedStep=index;return new NativeToolPlan.Resolved(tool.equals("phone_click_node")?NativeToolPlan.Tool.CLICK_NODE:NativeToolPlan.Tool.SCROLL_NODE,actual,fresh,current);
        },current);preparedCall=call;replaying=true;replayRoute=route;return new JSONObject().put("ok",true).put("status","prepared_guarded_route").put("routeId",id).put("steps",steps.length()).put("executionStarted",false).put("perStepOriginalApprovalRequired",true);
    }
    public NativeToolPlan take(String call,RunControl live)throws Exception {require(live);if(prepared==null||!call.equals(preparedCall))return null;NativeToolPlan value=prepared;prepared=null;preparedCall=null;return value;}
    public void after(String tool,JSONObject args,JSONObject receipt,JSONObject before,String operation,RunControl live)throws Exception {
        after(tool,args,receipt,before,before,operation,live);
    }
    public void after(String tool,JSONObject args,JSONObject receipt,JSONObject before,JSONObject after,String operation,RunControl live)throws Exception {
        require(live);if(invalid||replaying||restored||supports(tool)||tool.startsWith("run_")||tool.equals("phone_prepare_sequence")||tool.equals("phone_observe")||tool.equals("phone_wait")||tool.equals("phone_query")||tool.equals("phone_extract"))return;
        if(!tool.equals("phone_click_node")&&!tool.equals("phone_scroll_node")){if(tool.startsWith("phone_"))invalid=true;return;}
        if(operation==null||learned.length()>=4||!Boolean.TRUE.equals(receipt.opt("ok"))||receipt.has("accepted")&&!Boolean.TRUE.equals(receipt.opt("accepted"))||receipt.optBoolean("requiresReconciliation")){invalid=true;return;}
        JSONObject target=null;JSONArray nodes=before.optJSONArray("nodes");for(int i=0;nodes!=null&&i<nodes.length();i++)if(args.optString("nodeId").equals(nodes.getJSONObject(i).optString("id")))target=nodes.getJSONObject(i);
        if(target==null||target.optBoolean("password")||target.optString("resourceId").isEmpty()||tool.equals("phone_click_node")&&!PhoneActionPolicy.routeNavigationLabel(target.optString("text"))){invalid=true;return;}
        String app=before.optString("packageName");long actualVersion=repository.packageVersion(app);if(app.isEmpty()||actualVersion<1||!packageName.isEmpty()&&(!packageName.equals(app)||version!=actualVersion)){invalid=true;return;}packageName=app;version=actualVersion;
        JSONObject selector=new JSONObject().put("resourceId",target.getString("resourceId")).put("role",target.optString("role")).put("textExact",target.optString("text"));unique(before,selector);
        if(!complete(before)||!complete(after)||!app.equals(after.optString("packageName"))){invalid=true;return;}
        JSONObject step=new JSONObject().put("tool",tool).put("selector",selector).put("beforeAnchors",anchors(before)).put("afterAnchors",anchors(after));if(tool.equals("phone_scroll_node"))step.put("direction",args.getString("direction"));learned.put(step);operations.put(operation);
    }
    public boolean replayPostcondition(String tool,JSONObject receipt,JSONObject after)throws Exception {if(!replaying||replayRoute==null||resolvedStep<0)return true;JSONObject step=replayRoute.getJSONArray("steps").getJSONObject(resolvedStep);if(!step.getString("tool").equals(tool))return true;resolvedStep=-1;try{checkRoute(replayRoute,after);return Boolean.TRUE.equals(receipt.opt("ok"))&&anchorsMatch(after,step.optJSONArray("afterAnchors"));}catch(SecurityException diverged){return false;}}
    public JSONObject candidate(RunControl live)throws Exception {require(live);if(invalid||replaying||restored||learned.length()==0)return null;RunControl.HostRunIdentity identity=live.hostRunIdentity();if(identity==null)return null;JSONObject value=new JSONObject().put("format","pocketworld.phone-route-candidate.v1").put("routeId",java.util.UUID.randomUUID().toString()).put("sourceTaskId",task).put("sourceRunId",identity.runId()).put("sourceEpoch",identity.epoch()).put("goal",goal).put("packageName",packageName).put("packageVersion",version).put("steps",learned).put("operationIds",operations).put("businessVerified",false).put("requiresOwnerSuccess",true);return value.put("digest",digest(value));}
    private void require(RunControl live)throws Exception {if(live!=original||live.isPaused())throw new SecurityException("不是路线原控制器");live.check();}
    private void checkRoute(JSONObject route,JSONObject observation)throws Exception {if(observation==null||!observation.optBoolean("ok",true)||!route.getString("packageName").equals(observation.optString("packageName"))||repository.packageVersion(route.getString("packageName"))!=route.getLong("packageVersion")||!complete(observation))throw new SecurityException("路线应用、版本或完整当前树不符");}
    private static boolean complete(JSONObject observation){if(observation.optInt("treeSchemaVersion")!=1||observation.optBoolean("truncated"))return false;JSONObject sources=observation.optJSONObject("observationSources");JSONArray windows=observation.optJSONArray("windows");if(sources==null||!sources.optBoolean("treeAvailable")||windows==null||windows.length()<1)return false;for(int i=0;i<windows.length();i++){JSONObject w=windows.optJSONObject(i);if(w==null||!w.optBoolean("rootAvailable")||w.optBoolean("truncated"))return false;}return true;}
    private static JSONObject unique(JSONObject observation,JSONObject selector)throws Exception {JSONObject found=null;JSONArray nodes=observation.optJSONArray("nodes");for(int i=0;nodes!=null&&i<nodes.length();i++){JSONObject n=nodes.getJSONObject(i);if(selector.getString("resourceId").equals(n.optString("resourceId"))&&selector.getString("role").equals(n.optString("role"))&&selector.getString("textExact").equals(n.optString("text"))){if(found!=null)throw new SecurityException("路线目标不唯一");found=n;}}if(found==null||!found.optBoolean("visible",true)||!found.optBoolean("enabled",true)||found.optBoolean("password"))throw new SecurityException("路线目标缺失或私密");return found;}
    private static JSONArray anchors(JSONObject observation)throws Exception {java.util.Set<String> values=new java.util.LinkedHashSet<>();JSONArray nodes=observation.optJSONArray("nodes");for(int i=0;nodes!=null&&i<nodes.length()&&values.size()<4;i++){JSONObject node=nodes.getJSONObject(i);String text=node.optString("text").trim();if(!node.optBoolean("password")&&node.optBoolean("visible",true)&&!text.isEmpty()&&text.length()<=80)values.add(text);}return new JSONArray(values);}
    private static boolean anchorsMatch(JSONObject observation,JSONArray expected)throws Exception {if(expected==null||expected.length()==0)return false;JSONArray seen=anchors(observation);int matched=0;for(int i=0;i<expected.length();i++)for(int j=0;j<seen.length();j++)if(expected.getString(i).equals(seen.getString(j))){matched++;break;}return matched>=Math.min(2,expected.length());}
    public static String digest(JSONObject source)throws Exception {JSONObject value=new JSONObject(source.toString());value.remove("digest");return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(canonical(value).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
    private static String canonical(Object value)throws Exception {if(value instanceof JSONObject o){java.util.List<String> keys=new java.util.ArrayList<>();o.keys().forEachRemaining(keys::add);java.util.Collections.sort(keys);StringBuilder b=new StringBuilder("{");for(String k:keys){if(b.length()>1)b.append(',');b.append(JSONObject.quote(k)).append(':').append(canonical(o.get(k)));}return b.append('}').toString();}if(value instanceof JSONArray a){StringBuilder b=new StringBuilder("[");for(int i=0;i<a.length();i++){if(i>0)b.append(',');b.append(canonical(a.get(i)));}return b.append(']').toString();}return value instanceof String?JSONObject.quote((String)value):String.valueOf(value);}
    public void disableLearning(){invalid=true;}
    public void close(){if(prepared!=null)prepared.close();}
}
